const routes = [ { path: '/', redirect: '/login' }, { path: '/login', name: 'login', component: LoginView }, { path: '/', component: MainLayout, children: [ { path: 'dashboard', name: 'dashboard', component: DashboardView }, { path: 'recipients', component: RecipientListView }, { path: 'recipients/new', component: RecipientCreateView }, { path: 'recipients/:id', component: RecipientDetailView }, { path: 'donors', component: DonorListView }, { path: 'donors/new', component: DonorCreateView }, { path: 'donors/:id', component: DonorDetailView }, { path: 'matching', component: MatchingDashboardView }, { path: 'matching/virtual-crossmatch', component: VirtualCrossmatchView }, { path: 'waiting-list/recipients', component: WaitingListRecipientsView } ] } ]
